const yaml = $json.data;

const lines = yaml.split('\n');

const config = {
  center: {},
  categories: [],
};

let section = null;

for (const line of lines) {
  const trimmed = line.trim();

  if (!trimmed || trimmed.startsWith('#')) {
    continue;
  }

  if (line.startsWith('center:')) {
    section = 'center';
    continue;
  }

  if (line.startsWith('radius_km:')) {
    config.radius_km = Number(line.split(':')[1].trim());
    section = null;
    continue;
  }

  if (line.startsWith('lookahead_weeks:')) {
    config.lookahead_weeks = Number(line.split(':')[1].trim());
    section = null;
    continue;
  }

  if (line.startsWith('categories:')) {
    section = 'categories';
    continue;
  }

  if (section === 'center' && trimmed.includes(':')) {
    const [key, value] = trimmed.split(':').map(v => v.trim());

    if (key === 'name') {
      config.center.name = value;
    } else {
      config.center[key] = Number(value);
    }

    continue;
  }

  if (section === 'categories' && trimmed.startsWith('- ')) {
    config.categories.push(trimmed.slice(2).trim());
  }
}

return [{ json: config }];

const config = $json;

const now = new Date();

// Sunday = 0, Monday = 1, ..., Saturday = 6
const day = now.getDay();

// Find the next Monday
const daysUntilMonday = day === 0 ? 1 : 8 - day;

const startDate = new Date(now);
startDate.setDate(startDate.getDate() + daysUntilMonday);
startDate.setHours(0, 0, 0, 0);

// Three complete weeks: Monday → Sunday
const endDate = new Date(startDate);
endDate.setDate(
  endDate.getDate() + (config.lookahead_weeks * 7) - 1
);
endDate.setHours(23, 59, 59, 999);

// Format using local date components.
// Avoid toISOString() because it can shift the date across midnight.
const formatDate = (date) => {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');

  return `${year}-${month}-${day}`;
};

return [{
  json: {
    ...config,
    start_date: formatDate(startDate),
    end_date: formatDate(endDate)
  }
}];

const output = [];

for (const item of $input.all()) {
  const query = item.json.query;
  const results = item.json.results || [];

  for (const result of results) {
    output.push({
      json: {
        source_query: query,
        url: result.url,
        title: result.title,
        content: result.content,
        score: result.score,
      },
    });
  }
}

return output;

const seen = new Set();
const output = [];

for (const item of $input.all()) {
  const url = item.json.url;

  if (!url || seen.has(url)) {
    continue;
  }

  seen.add(url);

  output.push({
    json: item.json,
  });
}

return output;

const output = [];

function decode(value) {
  if (value == null) return null;

  return String(value)
    .replace(/\\u([0-9a-fA-F]{4})/g, (_, hex) =>
      String.fromCharCode(parseInt(hex, 16))
    )
    .replace(/\\\//g, '/')
    .replace(/\\"/g, '"')
    .replace(/&amp;/g, '&');
}

function cleanText(value) {
  if (value == null) return null;

  return String(value)
    .replace(/\s+/g, ' ')
    .trim();
}

function getField(raw, field) {
  const regex = new RegExp(
    `"${field}"\\s*:\\s*"((?:\\\\.|[^"])*)"`
  );

  const match = raw.match(regex);

  if (!match) return null;

  return decode(match[1]);
}

function normalizeDate(value) {
  if (!value) return null;

  const match = String(value).match(
    /^(\d{4})-(\d{2})-(\d{2})/
  );

  if (!match) return null;

  return `${match[1]}-${match[2]}-${match[3]}`;
}

function extractTime(value) {
  if (!value) return null;

  const text = String(value);

  // 12-hour format: 07:00 pm / 09:00 PM
  let match = text.match(
    /\b(\d{1,2}):(\d{2})\s*(am|pm)\b/i
  );

  if (match) {
    let hour = Number(match[1]);
    const minute = match[2];
    const period = match[3].toLowerCase();

    if (period === 'pm' && hour !== 12) {
      hour += 12;
    }

    if (period === 'am' && hour === 12) {
      hour = 0;
    }

    return `${String(hour).padStart(2, '0')}:${minute}`;
  }

  // 24-hour format
  match = text.match(
    /\b([01]?\d|2[0-3]):([0-5]\d)\b/
  );

  if (match) {
    return `${String(Number(match[1])).padStart(2, '0')}:${match[2]}`;
  }

  // Finnish format: klo 19 / klo 19.30 / kl. 19.30
  match = text.match(
    /\b(?:klo|kl\.?)\s*(\d{1,2})(?::|\.)(\d{2})?\b/i
  );

  if (match) {
    const hour = Number(match[1]);
    const minute = match[2] ?? '00';

    return `${String(hour).padStart(2, '0')}:${minute}`;
  }

  return null;
}

function parseAlleventsDisplayDate(display) {
  if (!display) return null;

  const match = String(display).match(
    /^[A-Za-z]{3}\s+([A-Za-z]{3})\s+(\d{1,2})\s+(\d{4})/i
  );

  if (!match) return null;

  const months = {
    jan: '01',
    feb: '02',
    mar: '03',
    apr: '04',
    may: '05',
    jun: '06',
    jul: '07',
    aug: '08',
    sep: '09',
    oct: '10',
    nov: '11',
    dec: '12',
  };

  const month =
    months[match[1].toLowerCase()];

  if (!month) return null;

  return `${match[3]}-${month}-${String(match[2]).padStart(2, '0')}`;
}

function isEventType(type) {
  if (typeof type === 'string') {
    return (
      type === 'Event' ||
      /Event$/i.test(type)
    );
  }

  if (Array.isArray(type)) {
    return type.some(
      t =>
        typeof t === 'string' &&
        (
          t === 'Event' ||
          /Event$/i.test(t)
        )
    );
  }

  return false;
}

function getJsonLdTime(event) {
  const startDate =
    event.startDate ||
    event.startTime ||
    null;

  const timeFromStart = extractTime(startDate);

  if (timeFromStart && timeFromStart !== '00:00') {
    return timeFromStart;
  }

  const timeFromDescription =
    extractTime(event.description);

  if (timeFromDescription) {
    return timeFromDescription;
  }

  return timeFromStart;
}

function collectJsonLdEvents(
  value,
  result = []
) {
  if (!value) return result;

  if (Array.isArray(value)) {
    for (const item of value) {
      collectJsonLdEvents(item, result);
    }

    return result;
  }

  if (typeof value !== 'object') {
    return result;
  }

  if (isEventType(value['@type'])) {
    result.push(value);
  }

  if (Array.isArray(value['@graph'])) {
    collectJsonLdEvents(
      value['@graph'],
      result
    );
  }

  if (value.event) {
    collectJsonLdEvents(
      value.event,
      result
    );
  }

  return result;
}

function extractJsonLd(
  html,
  pageUrl
) {
  const results = [];

  const matches = [
    ...html.matchAll(
      /<script[^>]*type=["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/gi
    )
  ];

  for (const match of matches) {
    const rawJson =
      match[1]?.trim();

    if (!rawJson) continue;

    try {
      const parsed =
        JSON.parse(rawJson);

      const events =
        collectJsonLdEvents(parsed);

      for (const event of events) {
        const name =
          cleanText(event.name);

        if (!name) continue;

        const startDate =
          normalizeDate(event.startDate);

        if (!startDate) continue;

        const location =
          typeof event.location === 'object'
            ? event.location
            : {};

        const address =
          typeof location.address === 'object'
            ? location.address
            : {};

        const city =
          cleanText(
            address.addressLocality ||
            location.addressLocality ||
            null
          );

        const venue =
          cleanText(
            location.name ||
            null
          );

        const latitude =
          location.geo?.latitude ??
          null;

        const longitude =
          location.geo?.longitude ??
          null;

        const url =
          event.url ||
          pageUrl ||
          null;

        results.push({
          json: {
            name,

            startDate,

            endDate:
              normalizeDate(event.endDate) ||
              startDate,

            time:
              getJsonLdTime(event),

            price:
              event.offers?.price ??
              null,

            location: {
              venue,

              city,

              address:
                cleanText(
                  address.streetAddress
                ),

              latitude:
                latitude !== null
                  ? Number(latitude)
                  : null,

              longitude:
                longitude !== null
                  ? Number(longitude)
                  : null,
            },

            description:
              cleanText(
                event.description
              ),

            url,

            sourceUrls:
              url
                ? [url]
                : [],

            sourceType:
              'jsonld',
          },
        });
      }

    } catch {
      // Ignore invalid JSON-LD.
    }
  }

  return results;
}

function extractAllevents(
  html,
  pageUrl
) {
  const results = [];

  const matches = [
    ...html.matchAll(
      /\\?"event_id\\?"\s*:\s*\\?"[^"]+\\?"\s*,\s*\\?"eventname\\?"/g
    )
  ];

  for (
    let i = 0;
    i < matches.length;
    i++
  ) {
    const start =
      matches[i].index;

    if (start == null) continue;

    const end =
      i + 1 < matches.length
        ? matches[i + 1].index
        : html.length;

    const raw =
      html.slice(start, end);

    const eventId =
      getField(raw, 'event_id');

    const name =
      getField(raw, 'eventname');

    if (!eventId || !name) {
      continue;
    }

    const country =
      getField(raw, 'country');

    // Ignore foreign events on Allevents listing pages.
    if (
      country &&
      country.toLowerCase() !== 'finland'
    ) {
      continue;
    }

    const startDisplay =
      getField(
        raw,
        'start_time_display'
      );

    const date =
      parseAlleventsDisplayDate(
        startDisplay
      );

    if (!date) continue;

    const venue =
      getField(
        raw,
        'location'
      );

    const city =
      getField(
        raw,
        'city'
      );

    const street =
      getField(
        raw,
        'street'
      );

    const fullAddress =
      getField(
        raw,
        'full_address'
      );

    const latitude =
      getField(
        raw,
        'latitude'
      );

    const longitude =
      getField(
        raw,
        'longitude'
      );

    const eventUrl =
      getField(
        raw,
        'event_url'
      );

    const description =
      getField(
        raw,
        'short_description'
      ) ||
      getField(
        raw,
        'description'
      );

    // Prefer the actual event display time.
    let time =
      extractTime(
        startDisplay
      );

    // Fall back to description.
    if (!time) {
      time =
        extractTime(
          description
        );
    }

    results.push({
      json: {
        name:
          cleanText(name),

        startDate:
          date,

        endDate:
          date,

        time,

        price:
          null,

        location: {
          venue:
            cleanText(venue),

          city:
            cleanText(city),

          address:
            cleanText(
              street ||
              fullAddress ||
              venue
            ),

          latitude:
            latitude !== null
              ? Number(latitude)
              : null,

          longitude:
            longitude !== null
              ? Number(longitude)
              : null,
        },

        description:
          cleanText(description),

        url:
          eventUrl ||
          pageUrl ||
          null,

        sourceUrls:
          eventUrl
            ? [eventUrl]
            : pageUrl
              ? [pageUrl]
              : [],

        sourceType:
          'allevents',

        eventId,
      },
    });
  }

  return results;
}


/*
 * =========================================================
 * PROCESS ONE FETCHED PAGE
 * =========================================================
 *
 * Loop Over Items sends one page at a time.
 */

const html =
  String(
    $json.data ?? ''
  );

const pageUrl =
  $json.url ??
  null;

if (!html) {
  return [];
}


/*
 * Extract JSON-LD events.
 */

const jsonLdEvents =
  extractJsonLd(
    html,
    pageUrl
  );


/*
 * Extract Allevents events.
 */

const alleventsEvents =
  html
    .toLowerCase()
    .includes('allevents')
      ? extractAllevents(
          html,
          pageUrl
        )
      : [];


/*
 * Combine both sources.
 *
 * Deduplication happens later.
 */

const events = [
  ...jsonLdEvents,
  ...alleventsEvents,
];

return {
  json: {
    events: events.map(item => item.json),
  },
};

const cityCoordinates = {
  Joutsa: [61.7417, 26.1142],
  Jyväskylä: [62.2426, 25.7473],
  Lahti: [60.9827, 25.6615],
  Heinola: [61.2056, 26.0388],
  Jämsä: [61.8642, 25.1900],
  Hartola: [61.5869, 26.0156],
  Sysmä: [61.5015, 25.6832],
  Mäntyharju: [61.4167, 26.8833],
  Mikkeli: [61.6886, 27.2723],
  Pieksämäki: [62.3000, 27.1333],
  Suonenjoki: [62.6167, 27.1333],
  Keuruu: [62.2667, 24.7000],
  Äänekoski: [62.6000, 25.7333],
  Toivakka: [62.1000, 26.0833],
  Luhanka: [61.8000, 25.7000],
  Espoo: [60.2055, 24.6559],
  Helsinki: [60.1699, 24.9384],
};

const results = [];

for (const item of $input.all()) {
  const event = { ...item.json };

  const rawLat = event.location?.latitude;
  const rawLon = event.location?.longitude;

  const hasCoordinates =
    rawLat !== null &&
    rawLat !== undefined &&
    rawLon !== null &&
    rawLon !== undefined &&
    Number.isFinite(Number(rawLat)) &&
    Number.isFinite(Number(rawLon));

  // Existing coordinates are already the best available data.
  if (hasCoordinates) {
    results.push({
      json: {
        ...event,
        locationStatus: 'coordinates_available',
        needsGeocoding: false,
      },
    });

    continue;
  }

  // Try resolving from the city.
  const city = event.location?.city;

  if (city && cityCoordinates[city]) {
    const [latitude, longitude] = cityCoordinates[city];

    results.push({
      json: {
        ...event,
        location: {
          ...event.location,
          latitude,
          longitude,
        },
        locationStatus: 'city_resolved',
        needsGeocoding: false,
      },
    });

    continue;
  }

  // Still unresolved.
  results.push({
    json: {
      ...event,
      locationStatus: 'needs_geocoding',
      needsGeocoding: true,
    },
  });
}

return results;

const events = $input.all().map(item => item.json);

const groups = [];

function normalize(value) {
  return String(value ?? '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();
}

function getArtistName(name) {
  let value = String(name ?? '');

  // Remove everything after @
  value = value.split('@')[0];

  // Remove common source-specific event suffixes.
  //
  // Example:
  // "Antti Autio - Lahti - Finlandia-Klubi - Oct 2, 2026"
  //
  // becomes:
  // "Antti Autio"
  value = value.replace(
    /\s+-\s+(?:[^-]+)\s+-\s+(?:[^-]+)\s+-\s+\w+\s+\d{1,2},\s+\d{4}$/i,
    ''
  );

  // Also handle:
  // "Future Palace - Jyvaskyla - Lutakko - Oct 2, 2026"
  value = value.replace(
    /\s+-\s+[^-]+?\s+-\s+[^-]+?\s+-\s+\w+\s+\d{1,2},\s+\d{4}$/i,
    ''
  );

  return normalize(value);
}

function getDate(event) {
  return event.startDate?.slice(0, 10) ?? '';
}

function getCoordinates(event) {
  const lat = Number(event.location?.latitude);
  const lon = Number(event.location?.longitude);

  if (
    !Number.isFinite(lat) ||
    !Number.isFinite(lon)
  ) {
    return null;
  }

  return { lat, lon };
}

function distanceBetween(a, b) {
  if (!a || !b) {
    return Infinity;
  }

  const R = 6371;

  const dLat =
    (b.lat - a.lat) * Math.PI / 180;

  const dLon =
    (b.lon - a.lon) * Math.PI / 180;

  const x =
    Math.sin(dLat / 2) ** 2 +
    Math.cos(a.lat * Math.PI / 180) *
    Math.cos(b.lat * Math.PI / 180) *
    Math.sin(dLon / 2) ** 2;

  return (
    R *
    2 *
    Math.atan2(
      Math.sqrt(x),
      Math.sqrt(1 - x)
    )
  );
}

function hasUsefulLocation(event) {
  return Boolean(
    event.location?.venue ||
    event.location?.city ||
    getCoordinates(event)
  );
}

function mergeEvent(existing, event) {
  // Keep all source URLs.
  const urls = [
    ...(existing.sourceUrls ?? []),
    ...(event.sourceUrls ?? []),
    ...(event.url ? [event.url] : []),
  ];

  existing.sourceUrls = [
    ...new Set(urls.filter(Boolean)),
  ];

  // Prefer the longer/more descriptive name.
  if (
    event.name &&
    (!existing.name ||
      event.name.length > existing.name.length)
  ) {
    existing.name = event.name;
  }

  // Prefer description when missing.
  if (
    !existing.description &&
    event.description
  ) {
    existing.description = event.description;
  }

  // Prefer coordinates.
  if (
    !getCoordinates(existing) &&
    getCoordinates(event)
  ) {
    existing.location = {
      ...existing.location,
      ...event.location,
    };

    existing.distanceKm = event.distanceKm;
  }

  // Fill missing location fields.
  existing.location = {
    ...event.location,
    ...existing.location,
  };

  if (
    !existing.location?.venue &&
    event.location?.venue
  ) {
    existing.location.venue =
      event.location.venue;
  }

  if (
    !existing.location?.city &&
    event.location?.city
  ) {
    existing.location.city =
      event.location.city;
  }

  if (
    !existing.location?.address &&
    event.location?.address
  ) {
    existing.location.address =
      event.location.address;
  }

  // Prefer the calculated distance when available.
  if (
    existing.distanceKm == null &&
    event.distanceKm != null
  ) {
    existing.distanceKm = event.distanceKm;
  }

  return existing;
}


for (const event of events) {
  const artist = getArtistName(event.name);
  const date = getDate(event);
  const coordinates = getCoordinates(event);

  if (!artist || !date) {
    groups.push({
      ...event,
      sourceUrls: event.url
        ? [event.url]
        : [],
    });

    continue;
  }

  let matchingGroup = null;

  for (const existing of groups) {
    const existingArtist =
      getArtistName(existing.name);

    const existingDate =
      getDate(existing);

    if (
      artist !== existingArtist ||
      date !== existingDate
    ) {
      continue;
    }

    const existingCoordinates =
      getCoordinates(existing);

    /*
     * If both events have coordinates,
     * require them to be geographically close.
     *
     * This prevents:
     *
     * Artist A — Helsinki
     * Artist A — Jyväskylä
     *
     * on the same date from being merged.
     */
    if (
      coordinates &&
      existingCoordinates
    ) {
      const distance =
        distanceBetween(
          coordinates,
          existingCoordinates
        );

      if (distance > 5) {
        continue;
      }
    }

    matchingGroup = existing;
    break;
  }

  if (matchingGroup) {
    mergeEvent(
      matchingGroup,
      event
    );
  } else {
    groups.push({
      ...event,
      sourceUrls: [
        ...(event.sourceUrls ?? []),
        ...(event.url ? [event.url] : []),
      ].filter(Boolean),
    });
  }
}


return groups.map(event => ({
  json: event,
}));

const events = $input.all();

return events.map(item => {
  const event = item.json;

  return {
    json: {
      name: event.name,
      date: event.startDate?.slice(0, 10) ?? null,
      time: event.time || event.startDate?.slice(11, 16) || null,
      price: event.price ?? null,

      venue: event.location?.venue ?? null,
      city: event.location?.city ?? null,
      address: event.location?.address ?? null,

      distanceKm: event.distanceKm ?? null,

      description: event.description ?? null,

      sourceUrls: event.sourceUrls ?? [],
    },
  };
});

const events = $input.all().map(item => item.json);

// Production uses Calculate Date Range.
// When testing from the saved JSON branch, use the test range.
let START_DATE = '2026-09-28';
let END_DATE = '2026-10-18';

try {
  const dateRange = $('Calculate Date Range').first().json;

  if (dateRange.start_date) {
    START_DATE = dateRange.start_date;
  }

  if (dateRange.end_date) {
    END_DATE = dateRange.end_date;
  }
} catch {}


function inRange(date) {
  return date >= START_DATE && date <= END_DATE;
}


function extractOccurrenceDates(description) {
  if (!description) {
    return [];
  }

  const dates = new Set();

  // --------------------------------------------------
  // YYYY-MM-DD
  // --------------------------------------------------

  const isoMatches =
    description.match(/\b20\d{2}-\d{2}-\d{2}\b/g) ?? [];

  for (const date of isoMatches) {
    if (inRange(date)) {
      dates.add(date);
    }
  }


  // --------------------------------------------------
  // Month DD, YYYY
  // Example:
  // October 30, 2026
  // --------------------------------------------------

  const monthNames = [
    'January',
    'February',
    'March',
    'April',
    'May',
    'June',
    'July',
    'August',
    'September',
    'October',
    'November',
    'December',
  ];

  const monthPattern = new RegExp(
    `\\b(${monthNames.join('|')})\\s+(\\d{1,2}),\\s+(20\\d{2})\\b`,
    'gi'
  );

  let match;

  while ((match = monthPattern.exec(description)) !== null) {
    const month = monthNames.findIndex(
      month =>
        month.toLowerCase() === match[1].toLowerCase()
    ) + 1;

    const day = Number(match[2]);
    const year = Number(match[3]);

    const date =
      `${year}-${String(month).padStart(2, '0')}-${String(day).padStart(2, '0')}`;

    if (inRange(date)) {
      dates.add(date);
    }
  }


  return [...dates].sort();
}


const results = [];


for (const event of events) {
  if (!event.startDate) {
    continue;
  }

  const startDate = event.startDate.slice(0, 10);

  const endDate = event.endDate
    ? event.endDate.slice(0, 10)
    : startDate;


  // --------------------------------------------------
